from decimal import Decimal, ROUND_FLOOR


def tickRound(prices, cabinet, ticks):
    cab = Decimal(str(cabinet))
    out = []
    for p in prices:
        dp = Decimal(str(p))
        if dp == cab:
            out.append(p)
            continue
        for lo, hi, w in ticks:
            lo, hi, w = Decimal(str(lo)), Decimal(str(hi)), Decimal(str(w))
            if lo <= dp < hi:
                n = ((dp - lo) / w + Decimal("0.5")).to_integral_value(rounding=ROUND_FLOOR)
                out.append(float(lo + n * w))
                break
        else:
            out.append(p)  # outside every range: unchanged
    return out

class Solution {
    static class Tick { double lo, hi, width; Tick(double l, double h, double w){lo=l;hi=h;width=w;} }
    static class VariableTickTable { double cabinetPrice; List<Tick> ticks; }
    public List<Double> tickRound(List<Double> prices, VariableTickTable t) {
        List<Double> out = new ArrayList<>();
        for (double p : prices) {
            if (p == t.cabinetPrice) { out.add(p); continue; }
            for (Tick tk : t.ticks) {
                if (p >= tk.lo && p < tk.hi) {
                    double n = (p - tk.lo) / tk.width;
                    out.add(tk.lo + Math.floor(n + 0.5) * tk.width);
                    break;
                }
            }
        }
        return out;
    }
}

