vector<double> tickRound(const vector<double>& prices, const VariableTickTable& t) {
 vector<double> out;
 for (double p : prices) {
 if (p == t.cabinetPrice) { out.push_back(p); continue; }
 for (auto& tk : t.ticks) {
 if (p >= tk.lo && p < tk.hi) {
 double n = (p - tk.lo) / tk.width;
 double rounded = tk.lo + floor(n + 0.5) * tk.width;
 out.push_back(rounded);
 break;
 }
 }
 }
